## C++ 

```cpp
#include <bits/stdc++.h>
using namespace std;

string transformALI(const string& s) {
    // 只统计 A、L、I 的数量，其他字符忽略
    int cnt[3] = {0, 0, 0}; // 0->A, 1->L, 2->I
    for (char c : s) {
        if (c == 'A') cnt[0]++;
        else if (c == 'L') cnt[1]++;
        else if (c == 'I') cnt[2]++;
    }

    // 构造答案
    string ans;
    int p = 0; // 当前起始指针，0:A,1:L,2:I
    int total = cnt[0] + cnt[1] + cnt[2];
    while (total > 0) {
        bool placed = false;
        for (int k = 0; k < 3; ++k) {
            int idx = (p + k) % 3;
            if (cnt[idx] > 0) {
                ans.push_back(idx == 0 ? 'A' : (idx == 1 ? 'L' : 'I'));
                cnt[idx]--;
                total--;
                p = (idx + 1) % 3; // 下次从下一个字符开始
                placed = true;
                break;
            }
        }
        if (!placed) break; // 理论上不会发生，因为 total > 0
    }

    if (ans.empty()) return "-1";
    return ans;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;
    string s;
    string dummy;
    getline(cin, dummy); // 吃掉行尾

    for (int i = 0; i < n; ++i) {
        getline(cin, s);
        cout << transformALI(s) << "\n";
    }
    return 0;
}
```

