import sys

def transform_ali(s: str) -> str:
    # 只统计 A、L、I 数量
    cnt = [0, 0, 0]  # 0->A, 1->L, 2->I
    for ch in s:
        if ch == 'A':
            cnt[0] += 1
        elif ch == 'L':
            cnt[1] += 1
        elif ch == 'I':
            cnt[2] += 1

    res = []
    p = 0  # 当前起始指针
    total = sum(cnt)
    while total > 0:
        placed = False
        for k in range(3):
            idx = (p + k) % 3
            if cnt[idx] > 0:
                res.append('A' if idx == 0 else ('L' if idx == 1 else 'I'))
                cnt[idx] -= 1
                total -= 1
                p = (idx + 1) % 3
                placed = True
                break
        if not placed:
            break

    return "".join(res) if res else "-1"

def main():
    data = sys.stdin.read().splitlines()
    if not data:
        return
    n = int(data[0].strip())
    out = []
    line_idx = 1
    for _ in range(n):
        s = data[line_idx] if line_idx < len(data) else ""
        line_idx += 1
        out.append(transform_ali(s))
    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    main()
