import sys

def transform_ali(s: str) -> str:
    # 统计 A, L, I 的数量
    cnt = [0, 0, 0]  # 0 -> A, 1 -> L, 2 -> I
    for ch in s:
        if ch == 'A':
            cnt[0] += 1
        elif ch == 'L':
            cnt[1] += 1
        elif ch == 'I':
            cnt[2] += 1

    total = sum(cnt)
    if total == 0:
        return "-1"

    res = []
    p = 0  # 当前起始指针，0:A, 1:L, 2:I
    while total > 0:
        placed = False
        for k in range(3):
            idx = (p + k) % 3
            if cnt[idx] > 0:
                # 将对应字符加入结果
                if idx == 0:
                    res.append('A')
                elif idx == 1:
                    res.append('L')
                else:
                    res.append('I')
                cnt[idx] -= 1
                total -= 1
                p = (idx + 1) % 3  # 下一次从下一个字母开始
                placed = True
                break
        if not placed:  # 理论上不会发生，防御性break
            break

    return "".join(res)


def main():
    data = sys.stdin.read().splitlines()
    if not data:
        return
    n = int(data[0].strip())
    out_lines = []
    for i in range(1, n + 1):
        s = data[i] if i < len(data) else ""
        out_lines.append(transform_ali(s))
    sys.stdout.write("\n".join(out_lines))


if __name__ == "__main__":
    main()
